import{_ as a,o as e,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"NVMeoF in Ceph - Whats New and Whats Next?","description":"","frontmatter":{"title":"NVMeoF in Ceph - Whats New and Whats Next?","date":"2025-06-24T00:00:00.000Z","updated":"2025-06-24T00:00:00.000Z","tags":["Ceph","NVMe over TCP","Storage Gateway","High Availability","Ceph RBD"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/NVMeoF_in_Ceph_-_What_s_New_and_What_s_Next.md","filePath":"posts/2025/NVMeoF_in_Ceph_-_What_s_New_and_What_s_Next.md","lastUpdated":1780459816000}'),n={name:"posts/2025/NVMeoF_in_Ceph_-_What_s_New_and_What_s_Next.md"};function l(i,t,s,h,_,g){return e(),r("div",null,[...t[0]||(t[0]=[o('<h3 id="ceph-nvme-over-tcp-网关开发进展会议纪要" tabindex="-1"><strong>Ceph NVMe over TCP 网关开发进展会议纪要</strong> <a class="header-anchor" href="#ceph-nvme-over-tcp-网关开发进展会议纪要" aria-label="Permalink to &quot;**Ceph NVMe over TCP 网关开发进展会议纪要**&quot;">​</a></h3><h4 id="_1-会议概述" tabindex="-1"><strong>1. 会议概述</strong> <a class="header-anchor" href="#_1-会议概述" aria-label="Permalink to &quot;**1. 会议概述**&quot;">​</a></h4><ul><li><strong>主持人</strong>: Ail Caro（IBM 工程经理，负责 NVMe over TCP 网关及 Ceph RBD 团队）</li><li><strong>主要内容</strong>: <ul><li><strong>Tentacle</strong> 版本（非 Squid）中实现的 NVMe over TCP 网关功能。</li><li>即将在 Tentacle 中发布的新特性。</li><li>未来 roadmap 中的规划方向。</li></ul></li></ul><h4 id="_2-核心议题与讨论" tabindex="-1"><strong>2. 核心议题与讨论</strong> <a class="header-anchor" href="#_2-核心议题与讨论" aria-label="Permalink to &quot;**2. 核心议题与讨论**&quot;">​</a></h4><h5 id="_2-1-当前-nvme-over-tcp-网关架构" tabindex="-1"><strong>2.1 当前 NVMe over TCP 网关架构</strong> <a class="header-anchor" href="#_2-1-当前-nvme-over-tcp-网关架构" aria-label="Permalink to &quot;**2.1 当前 NVMe over TCP 网关架构**&quot;">​</a></h5><ul><li><strong>组件分层</strong>: 控制平面（管理配置和同步）和 IO 处理层（基于 SPDK）。</li><li><strong>数据映射</strong>: NVMe 命名空间对应 Ceph RBD 镜像。</li></ul><h5 id="_2-2-高可用性-high-availability" tabindex="-1"><strong>2.2 高可用性（High Availability）</strong> <a class="header-anchor" href="#_2-2-高可用性-high-availability" aria-label="Permalink to &quot;**2.2 高可用性（High Availability）**&quot;">​</a></h5><ul><li><strong>网关组</strong>: 共享配置，通过 NVMe ANA 组实现故障切换。</li><li><strong>监控机制</strong>: NVMe Monitor 检测故障，触发自动故障转移。</li><li><strong>故障恢复</strong>: 目标优化至 6-8 秒。</li></ul><h5 id="_2-3-安全与性能" tabindex="-1"><strong>2.3 安全与性能</strong> <a class="header-anchor" href="#_2-3-安全与性能" aria-label="Permalink to &quot;**2.3 安全与性能**&quot;">​</a></h5><ul><li><strong>加密</strong>: 支持传输层 TLS-PSK 和管理接口 mTLS 认证。</li><li><strong>QoS</strong>: 支持按命名空间限制 IOPS/吞吐量。</li></ul><h5 id="_2-4-新特性-tentacle-即将发布" tabindex="-1"><strong>2.4 新特性（Tentacle 即将发布）</strong> <a class="header-anchor" href="#_2-4-新特性-tentacle-即将发布" aria-label="Permalink to &quot;**2.4 新特性（Tentacle 即将发布）**&quot;">​</a></h5><ul><li><strong>Cluster Context 优化</strong>: 提升低命名空间数量时的并行性。</li><li><strong>自动负载均衡</strong>: 动态调整命名空间分布。</li><li><strong>命名空间掩码</strong>: 精细化控制主机访问权限。</li><li><strong>In-band 认证</strong>: 子系统与主机双向认证。</li></ul><h5 id="_2-5-监控与工具" tabindex="-1"><strong>2.5 监控与工具</strong> <a class="header-anchor" href="#_2-5-监控与工具" aria-label="Permalink to &quot;**2.5 监控与工具**&quot;">​</a></h5><ul><li><strong>Grafana 看板</strong>: 网关配置总览、性能监控、告警功能。</li><li><strong>CLI 集成</strong>: 将 NVMe CLI 合并至 Ceph CLI。</li></ul><h5 id="_2-6-未来-roadmap" tabindex="-1"><strong>2.6 未来 Roadmap</strong> <a class="header-anchor" href="#_2-6-未来-roadmap" aria-label="Permalink to &quot;**2.6 未来 Roadmap**&quot;">​</a></h5><ul><li><strong>NVMe Reservation</strong>: 支持 Windows 集群访问同一命名空间。</li><li><strong>Cancel Command</strong>: 解决 Admin Queue 限制问题。</li><li><strong>硬件加速</strong>: 利用 Intel DSA 优化 CRC 计算。</li><li><strong>扩展场景</strong>: Stretch Cluster 和 CSI Driver。</li></ul><h4 id="_3-行动计划" tabindex="-1"><strong>3. 行动计划</strong> <a class="header-anchor" href="#_3-行动计划" aria-label="Permalink to &quot;**3. 行动计划**&quot;">​</a></h4><ul><li><strong>短期交付</strong>: 完成NVMe Reservation 和 Cancel Command的代码审查，优化故障检测机制。</li><li><strong>长期规划</strong>: 开发动态命名空间迁移功能和优化 Grafana 监控看板。</li></ul><h4 id="_4-关键词保留" tabindex="-1"><strong>4. 关键词保留</strong> <a class="header-anchor" href="#_4-关键词保留" aria-label="Permalink to &quot;**4. 关键词保留**&quot;">​</a></h4><ul><li>Ceph, NVMe over TCP, SPDK, ANA groups, RBD, TLS-PSK, mTLS, QoS, Cluster Context, Grafana, CLI, NVMe Reservation, Intel DSA, Stretch Cluster, CSI Driver</li></ul><h4 id="_5-问题与后续" tabindex="-1"><strong>5. 问题与后续</strong> <a class="header-anchor" href="#_5-问题与后续" aria-label="Permalink to &quot;**5. 问题与后续**&quot;">​</a></h4><ul><li><strong>待验证</strong>: Intel DSA 和 TLS-PSK 的兼容性。</li><li><strong>用户反馈</strong>: 命名空间掩码的使用需求。</li></ul><p>（会议结束）</p>',23)])])}const c=a(n,[["render",l]]);export{u as __pageData,c as default};
